class Tokenizer:
    def __init__(self, delimiter=None):
        self.delimiter = delimiter

    def _split(self, text):
        parts = []
        current = ""
        for ch in text:
            is_delim = (ch == self.delimiter) if self.delimiter else (ch in " \t")
            if is_delim:
                parts.append(current)
                current = ""
            else:
                current += ch
        parts.append(current)
        return parts

    def tokenize(self, text):
        if text == "":
            return []
        return self._split(text)

    def count(self, text):
        return len(self.tokenize(text))

