from tokenizer import Tokenizer


def test_single_space():
    assert Tokenizer().tokenize("a b c") == ["a", "b", "c"]


def test_collapse_runs():
    t = Tokenizer()
    assert t.tokenize("a   b\t\tc") == ["a", "b", "c"]
    assert t.count("a   b\t\tc") == 3


def test_leading_trailing_whitespace():
    assert Tokenizer().tokenize("  hi  ") == ["hi"]


def test_delimiter_preserves_empty_fields():
    t = Tokenizer(delimiter=",")
    assert t.tokenize("a,,b") == ["a", "", "b"]
    assert t.count("a,,b") == 3


def test_delimiter_edges():
    assert Tokenizer(delimiter=",").tokenize(",a,") == ["", "a", ""]


def test_empty():
    assert Tokenizer().tokenize("") == []

